#!/bin/bash
# Autogenerated deployment script for clinvar-classify
set -e
cd "$(dirname "$0")"

echo "=== Building web client for clinvar-classify ==="
cd web
npm install
npm run build
cd ..

echo "=== Deploying to Hostinger via rsync ==="
# Note: Ensure you have added 'hostinger-portfolio' to your SSH config.
# If using env vars: rsync -avz --delete web/dist/ $HOSTINGER_USER@$HOSTINGER_HOST:/home/u918475266/public_html/clinvar-classify/
rsync -avz --delete web/dist/ hostinger-portfolio:/home/u918475266/public_html/clinvar-classify/

echo "=== Deployment for clinvar-classify completed successfully ==="
